import numpy as np

def detect_slip(signal, window, threshold):
    """Index of the first sample at which slip is detected, or None."""
    signal = np.asarray(signal, dtype=float)
    for i in range(window, len(signal)):
        d = np.diff(signal[i - window:i + 1])      # the last `window` sample-to-sample changes
        if np.sqrt(np.mean(d ** 2)) > threshold:
            return i
    return None

